#include "stdafx.h"//#include <locale>namespace ns_SystemReplace_Local{  static DWORD crctable32[256] = { 0 };  static BOOL bInitedTable32 = FALSE;  static void MakeCRC32Table(void)  {    for (UINT i = 0; i < 256; i++)    {      crctable32[i] = i;      for (UINT j = 0; j < 8; j++)        crctable32[i] = crctable32[i] & 1 ? (crctable32[i] >> 1) ^ 0xEDB88320 : crctable32[i] >> 1;    }    /*static const BYTE p[] = {0,1,2,4,5,7,8,10,11,12,16,22,23,26};    DWORD c;    DWORD n, k;    DWORD poly;    poly = 0L;    for (n = 0; n < _countof(p); n++)      poly |= 1L << (31 - p[n]);    for (n = 0; n < _countof(crctable32); n++)    {      c = n;      for (k = 0; k < 8; k++)        c = c & 1 ? poly ^ (c >> 1) : c >> 1;      crctable32[n] = c;    }*/  }  char _2upper( char c )  {    if( c>='а' && c <='я' )    {      c -= 'а';      c += 'А';    }    if( c>='a' && c <='z' )    {      c -= 'a';      c += 'Z';    }    return c;  }  DWORD crc32forString( LPCSTR pszString, bool bToUpper )  {    DWORD crc = 0xEDB88320;    //crc = crc ^ 0xffffffffL;    LPCSTR pCur = pszString;    while( *pCur )    {      char c = *pCur;      if( bToUpper )        c = /*toupper*/_2upper( c );      BYTE b = 0;      memcpy( &b, &c, sizeof(b) );      crc = crctable32[(crc ^ b) & 0xff] ^ (crc >> 8);      ++pCur;    }    return crc;// ^ 0xffffffffL;  }  static bool bLocaleChanged = false;}DWORD CreateHASH32( LPCSTR pszText, bool bToUpper ){  /*if( bToUpper )  {    if( !ns_SystemReplace_Local::bLocaleChanged )    {      char* Q = setlocale( LC_ALL, "Russian");      ns_SystemReplace_Local::bLocaleChanged = true;    }  }*/  if( !ns_SystemReplace_Local::bInitedTable32 )    ns_SystemReplace_Local::bInitedTable32 = TRUE, ns_SystemReplace_Local::MakeCRC32Table();  return ns_SystemReplace_Local::crc32forString( pszText, bToUpper );}